import org.openenglish.reader.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Real host model inference. Host timings are not phone latency claims. */
public final class IslandNativeTest {
 static int checks;static void check(boolean ok,String title){if(!ok)throw new AssertionError(title);checks++;System.out.println("PASS "+title);}
 static class Call implements LocalNative.Callbacks{boolean stop;int deltas;String streamed="";public boolean abort(){return stop;}public void text(String s){streamed=s;deltas++;}public void segment(long a,long b,String s){}}
 public static void main(String[] args)throws Exception{LocalNative.loadWhisper();LocalNative.loadLlama();System.loadLibrary("english_speech");Call cb=new Call();String[] lang={"zh","ja","zh"};String[] clips={"canto.wav","japanese.wav","mandarin.wav"};for(int i=0;i<3;i++){long start=System.nanoTime();String s=LocalNative.whisperLanguage(args[0],LocalWav.read(new File(args[4],clips[i])),2,lang[i],cb);System.out.println("ASR "+clips[i]+": "+s+" HOST_MS="+(System.nanoTime()-start)/1000000);check(!s.trim().isEmpty()&&!s.contains("\ufffd"),"real multilingual ASR produces valid text "+clips[i]);if(i==1)check(s.contains("コーヒー"),"Japanese coffee phrase recognized");if(i==2)check(s.contains("咖啡"),"Mandarin coffee phrase recognized");}check(LocalNative.whisperLoadCount()==1,"multilingual ASR reuses warmed model");boolean rejected=false;try{LocalNative.whisperLanguage(args[3],LocalWav.read(new File(args[4],"japanese.wav")),2,"ja",cb);}catch(IOException e){rejected=true;}check(rejected,"English-only model rejected for Japanese");String eng=LocalNative.whisper(args[3],LocalWav.read(new File(args[4],"english.wav")),2,cb);check(eng.toLowerCase(Locale.US).contains("ask not"),"original English ASR path preserved");Call cancel=new Call();cancel.stop=true;boolean cancelled=false;try{LocalNative.whisperLanguage(args[0],new float[16000],2,"ja",cancel);}catch(CancellationException e){cancelled=true;}check(cancelled,"multilingual recognition cancellation");
 for(String code:new String[]{"yue","ja","zh"}){String user=code.equals("ja")?"こんにちは。コーヒーをひとつください。":code.equals("zh")?"你好，我想要一杯咖啡。":"唔該，我想飲凍奶茶。";String prompt=IslandPrompt.qwen(IslandPrompt.instruction(code,"咖啡店点餐","喜欢少甜"),Collections.singletonList(new String[]{"user",user}));Call chat=new Call();long start=System.nanoTime();String reply=LocalNative.chat(args[1],prompt,3,96,chat);System.out.println("QWEN "+code+": "+reply+" HOST_MS="+(System.nanoTime()-start)/1000000);check(!reply.trim().isEmpty()&&chat.deltas>0,"real Qwen streams "+code);check(reply.equals(chat.streamed),"streamed final Qwen response matches "+code);}
 check(LocalNative.llamaLoadCount()==1,"Qwen model reused between target languages");for(String code:new String[]{"yue","ja","cmn"}){String phrase=code.equals("yue")?"你好呀，你想飲咩？":code.equals("ja")?"こんにちは。こーひーはいかがですか？":"你好，你想喝什么？";long start=System.nanoTime();float[] pcm=IslandSpeech.render(args[2],code,phrase,new Call());check(pcm!=null&&pcm.length>1600&&LocalWav.hasSignal(pcm),"real offline speech produces signal "+code);LessonAudio.writeSpeech(new File(args[4],"espeak-"+code+".wav"),pcm);System.out.println("SPEECH "+code+" seconds="+pcm.length/16000.0+" HOST_MS="+(System.nanoTime()-start)/1000000);}cancelled=false;try{IslandSpeech.render(args[2],"yue","你好",cancel);}catch(CancellationException e){cancelled=true;}check(cancelled,"offline speech cancellation before synth");LocalNative.releaseWhisper();LocalNative.releaseLlama();System.out.println("ISLAND_NATIVE_CHECKS: "+checks);}
}
